CREATE DATABASE IF NOT EXISTS dragon_shop CHARACTER SET utf8mb4; USE dragon_shop;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,rank_name VARCHAR(40) NOT NULL,price INT NOT NULL,minecraft VARCHAR(40) NOT NULL,contact VARCHAR(100),receipt VARCHAR(100) NOT NULL,status ENUM('pending','delivered','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
